+        } catch (final Exception e) {
+            LOGGER.error("Failed to register broker to controller", e);
+            return false;
+        }
+    }
+
+    /**
+     * Scheduling sync broker metadata form controller.
+     */
+    private void schedulingSyncBrokerMetadata() {
