+                    if (newMasterEpoch > this.masterEpoch) {
+                        if (StringUtils.isNoneEmpty(newMasterAddress)) {
+                            if (StringUtils.equals(newMasterAddress, this.localAddress)) {
+                                changeToMaster(newMasterEpoch, syncStateSet.getSyncStateSetEpoch());
