+                                if (brokerId > 0) {
+                                    changeToSlave(newMasterAddress, newMasterEpoch, brokerId);
+                                } else if (brokerId < 0) {
+                                    // If the brokerId is no existed, we should try register again.
+                                    registerBrokerToController();
+                                }
+                            }
+                        } else {
