+            this.checkSyncStateSetTaskFuture.cancel(false);
+        }
+        this.checkSyncStateSetTaskFuture = this.scheduledService.scheduleAtFixedRate(() -> {
+            final Set<String> newSyncStateSet = this.haService.maybeShrinkInSyncStateSet();
